'use strict';
window.OrthodoxFormation=(()=>{
  let pending,data,controller;
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const paragraphs=v=>String(v||'').split(/\n\s*\n/).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('');
  const label=v=>({'covered':'Readings included','partial':'Partial coverage','further-study':'Further study','introductory':'Introductory','intermediate':'Intermediate','advanced':'Advanced'}[v]||v);
  const safe=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}};
  const ext=(href,text)=>`<a href="${safe(href)}" target="_blank" rel="noopener noreferrer">${esc(text)}</a>`;
  const meta=s=>[s.author,s.work||s.title,s.edition,s.translator].filter(Boolean).join(' · ');
  async function load(){if(data)return data;if(!pending)pending=(window.OrthodoxResources?window.OrthodoxResources.json('content/formation.json').then(value=>({ok:true,json:async()=>value})):fetch('content/formation.json')).then(r=>{if(!r.ok)throw new Error('Study map unavailable');return r.json();}).then(value=>(data=value)).catch(e=>{pending=null;throw e;});return pending;}
  function unmount(){controller?.abort();controller=null;}
  function options(items,value,all){return `<option value="">${esc(all)}</option>`+items.map(item=>`<option value="${esc(item)}" ${item===value?'selected':''}>${esc(label(item))}</option>`).join('');}
  function sourceRecord(s){if(!s)return '';return `<div class="formation-source"><p>${ext(s.url,s.title)}</p><p class="reading-attribution">${esc(meta(s))}</p>${s.audience?`<p>Audience: ${esc(s.audience)}</p>`:''}${s.context?`<p>${esc(s.context)}</p>`:''}${s.attribution?`<p>${esc(s.attribution)}</p>`:''}<p class="formation-rights">${s.rightsUrl?ext(s.rightsUrl,s.rights||'Source rights'):esc(s.rights||'Rights not recorded')}${s.rightsNote?' · '+esc(s.rightsNote):''}</p></div>`;}
  function quoted(r,s){return `<article class="formation-reading" data-scripture-source="${esc(r.sourceId)}"><h3>${esc(r.title||s?.title||'Reading')}</h3>${r.kind==='quotation'?`<blockquote class="quoted-reading">${paragraphs(r.text)}</blockquote>`:r.kind==='summary'?`${paragraphs(r.text)}`:''}<p class="reading-locator">${esc(r.locator||'')}</p>${sourceRecord(s)}</article>`;}
  function mount(ctx){
    unmount();if(!ctx.root)return;controller=new AbortController();const active=controller,signal=active.signal;
    if(!data){ctx.root.innerHTML='<h1>Loading study resources…</h1>';load().then(()=>{if(controller===active)mount(ctx);}).catch(()=>{if(controller===active){ctx.root.innerHTML='<h1>Study resources unavailable</h1><p>The rest of the app remains available.</p><button type="button" data-formation-retry>Retry</button>';ctx.root.querySelector('button').onclick=()=>mount(ctx);}});return;}
    const {root,kind='coverage',params=new URLSearchParams(),lessons=[],modules=[],glossary={terms:[]},getState=()=>({completed:[]})}=ctx;
    const sources=ctx.sources instanceof Map?ctx.sources:new Map((ctx.sources||data.sources||[]).map(s=>[s.id,s]));
    const lessonMap=new Map(lessons.map(l=>[l.id,l])),termMap=new Map(glossary.terms.map(t=>[t.id,t]));
    const on=(type,fn)=>root.addEventListener(type,fn,{signal});
    const tabs=`<nav class="formation-tabs" aria-label="Study resources">${[['coverage','Learning map'],['protestant-path','Protestant background'],['scripture-library','Scripture and Fathers'],['source-guide','Understanding sources']].map(([id,title])=>`<a href="#/${id}" ${kind===id?'aria-current="page"':''}>${title}</a>`).join('')}</nav>`;
    const lessonLinks=ids=>`<ol class="formation-lesson-list">${ids.map(id=>lessonMap.get(id)).filter(Boolean).map(l=>`<li><a href="#/lesson/${esc(l.id)}">${esc(l.title)}</a>${getState().completed?.includes(l.id)?'<span class="formation-completed">Completed</span>':''}<small>${esc(label(l.depth||'introductory'))}</small></li>`).join('')}</ol>`;
    function queryState(keys){return Object.fromEntries(keys.map(k=>[k,params.get(k)||'']));}
    function replace(keys,query){const p=new URLSearchParams();keys.forEach(k=>{if(query[k])p.set(k,query[k]);});history.replaceState(null,'','#/'+kind+(p.size?'?'+p.toString():''));}
    if(kind==='coverage'){
      const keys=['q','domain','status','depth','topic'],query=queryState(keys),rows=data.coverage;
      root.innerHTML=`${tabs}<h1>Learning map</h1><p class="formation-scope">${esc(data.reviewStatus.coverageMeaning)}</p><div class="formation-totals">${['covered','partial','further-study'].map(status=>`<div><strong>${rows.filter(r=>r.status===status).length}</strong><span>${label(status)}</span></div>`).join('')}</div><section class="formation-filters" aria-label="Learning map filters"><label>Search topics<input type="search" data-filter="q" value="${esc(query.q)}"></label><label>Area<select data-filter="domain">${options([...new Set(rows.map(r=>r.domain))],query.domain,'All areas')}</select></label><label>Coverage<select data-filter="status">${options(['covered','partial','further-study'],query.status,'All coverage')}</select></label><label>Depth<select data-filter="depth">${options(['introductory','intermediate','advanced'],query.depth,'All depths')}</select></label><button type="button" data-reset-map>Reset</button></section><p id="formation-count" role="status"></p><div id="formation-results"></div>`;
      const render=()=>{const found=rows.filter(r=>(!query.domain||r.domain===query.domain)&&(!query.status||r.status===query.status)&&(!query.depth||r.depth===query.depth)&&(!query.topic||r.id===query.topic)&&norm([r.title,r.domain,r.gap,...r.lessonIds.map(id=>lessonMap.get(id)?.title||'')].join(' ')).includes(norm(query.q)));root.querySelector('#formation-count').textContent=`${found.length} of ${rows.length} topics`;root.querySelector('#formation-results').innerHTML=found.length?found.map(r=>`<article class="formation-topic" id="map-${esc(r.id)}"><div class="formation-topic-head"><h2>${esc(r.title)}</h2><span class="formation-status formation-${esc(r.status)}">${label(r.status)}</span></div><p class="reading-attribution">${esc(r.domain)} · ${esc(label(r.depth))}</p>${r.gap?`<p class="formation-gap">${esc(r.gap)}</p>`:''}${r.prerequisites.length?`<p class="formation-prerequisites">Read first: ${r.prerequisites.map(id=>{const row=rows.find(r=>r.id===id);return `<a href="#/coverage?topic=${esc(id)}">${esc(row?.title||id)}</a>`;}).join(' · ')}</p>`:''}${lessonLinks(r.lessonIds)}<p><a href="#/coverage?topic=${esc(r.id)}">Link to this topic</a></p></article>`).join(''):'<div class="empty"><h2>No topics found</h2><p>Change the filters or reset the map.</p></div>';replace(keys,query);};
      on('input',e=>{if(e.target.dataset.filter==='q'){query.q=e.target.value;query.topic='';render();}});on('change',e=>{if(e.target.dataset.filter){query[e.target.dataset.filter]=e.target.value;query.topic='';render();}});on('click',e=>{if(e.target.closest('[data-reset-map]')){keys.forEach(k=>query[k]='');root.querySelectorAll('[data-filter]').forEach(el=>el.value='');render();}});render();return;
    }
    if(kind==='protestant-path'){
      const keys=['q','category'],query=queryState(keys),rows=data.comparisons;
      root.innerHTML=`${tabs}<h1>Reading from a Protestant background</h1><p class="formation-scope">Named confessions and authors remain distinct. The categories organize reading; they do not declare agreement on every use of a term or the authority of every source.</p><section class="formation-filters" aria-label="Comparison filters"><label>Search topics<input type="search" data-filter="q" value="${esc(query.q)}"></label><label>Reading category<select data-filter="category">${options([...new Set(rows.map(r=>r.category))],query.category,'All categories')}</select></label></section><p id="formation-count" role="status"></p><div id="formation-results"></div>`;
      const render=()=>{const found=rows.filter(r=>(!query.category||r.category===query.category)&&norm([r.title,r.scope,...r.lessonIds.map(id=>lessonMap.get(id)?.title||'')].join(' ')).includes(norm(query.q)));root.querySelector('#formation-count').textContent=`${found.length} of ${rows.length} topics`;root.querySelector('#formation-results').innerHTML=found.length?found.map(r=>`<article class="formation-topic"><span class="formation-status">${esc(r.category)}</span><h2>${esc(r.title)}</h2><p class="formation-scope">${esc(r.scope)}</p>${r.scripture.length?`<p class="formation-scripture">${r.scripture.map(esc).join(' · ')}</p>`:''}${r.readings.length?`<details class="formation-excerpts"><summary>Read published confessional statements</summary>${r.readings.map(q=>quoted(q,sources.get(q.sourceId))).join('')}</details>`:''}${lessonLinks(r.lessonIds)}${r.termIds.some(id=>termMap.has(id))?`<p class="study-term-links">${r.termIds.map(id=>termMap.get(id)).filter(Boolean).map(t=>`<a href="#/term/${esc(t.id)}">${esc(t.term)}</a>`).join('')}</p>`:''}<details class="formation-excerpts"><summary>Read source selections from these lessons</summary>${r.lessonIds.map(id=>lessonMap.get(id)).filter(Boolean).map(l=>`<section><h3><a href="#/lesson/${esc(l.id)}">${esc(l.title)}</a></h3>${l.readings.filter(q=>q.kind==='quotation').slice(0,2).map(q=>quoted(q,sources.get(q.sourceId))).join('')}</section>`).join('')}</details></article>`).join(''):'<div class="empty"><h2>No topics found</h2></div>';replace(keys,query);};
      on('input',e=>{if(e.target.dataset.filter==='q'){query.q=e.target.value;render();}});on('change',e=>{if(e.target.dataset.filter==='category'){query.category=e.target.value;render();}});render();return;
    }
    if(kind==='scripture-library'){
      const rows=[];for(const lesson of lessons)for(const reading of lesson.scripture||[])rows.push({lesson,reading,authors:[...new Set(lesson.readings.filter(r=>r.kind==='quotation').map(r=>sources.get(r.sourceId)?.author).filter(Boolean))]});
      const keys=['q','author'],query=queryState(keys);root.innerHTML=`${tabs}<h1>Scripture and Fathers</h1><p class="formation-scope">Scripture passages are connected to the published readings in the same lesson. This is a curriculum association, not a claim that every accompanying author comments on every verse. Each author’s words and translation remain identified.</p><section class="formation-filters" aria-label="Scripture reading filters"><label>Search Scripture, topic, or author<input type="search" data-filter="q" value="${esc(query.q)}" placeholder="John 6, baptism, Irenaeus"></label><label>Accompanying author<select data-filter="author">${options([...new Set(rows.flatMap(r=>r.authors))].sort(),query.author,'All authors')}</select></label></section><p id="formation-count" role="status"></p><div id="formation-results"></div>`;
      let limit=24;
      const render=()=>{const found=rows.filter(r=>(!query.author||r.authors.includes(query.author))&&norm([r.reading.reference,r.reading.text,r.lesson.title,...r.authors].join(' ')).includes(norm(query.q)));root.querySelector('#formation-count').textContent=`${found.length} of ${rows.length} Scripture readings${found.length>limit?' · showing '+limit:''}`;root.querySelector('#formation-results').innerHTML=found.length?found.slice(0,limit).map(({lesson:l,reading:r,authors})=>`<article class="formation-topic"><h2 data-scripture-edition="kjv">${esc(r.reference)}</h2><p class="reading-attribution">${esc(r.translation)}</p><details><summary>Read passage</summary><blockquote class="quoted-reading" data-scripture-edition="kjv">${paragraphs(r.text)}</blockquote>${sourceRecord(sources.get(r.sourceId))}</details><h3><a href="#/lesson/${esc(l.id)}">${esc(l.title)}</a></h3><p>${authors.map(esc).join(' · ')}</p><details class="formation-excerpts"><summary>Published readings in this lesson</summary>${l.readings.filter(q=>q.kind==='quotation').map(q=>quoted(q,sources.get(q.sourceId))).join('')}</details></article>`).join('')+(found.length>limit?'<button type="button" data-more-scripture>Show more readings</button>':''):'<div class="empty"><h2>No readings found</h2><p>Try a shorter reference, a book name, or an author.</p></div>';replace(keys,query);};
      on('input',e=>{if(e.target.dataset.filter==='q'){query.q=e.target.value;limit=24;render();}});on('change',e=>{if(e.target.dataset.filter==='author'){query.author=e.target.value;limit=24;render();}});on('click',e=>{if(e.target.closest('[data-more-scripture]')){limit+=24;render();}});render();return;
    }
    if(kind==='source-guide'){
      const keys=['q'],query=queryState(keys);const terms=data.glossarySupport.map(s=>({...s,term:termMap.get(s.termId)})).filter(s=>s.term);
      root.innerHTML=`${tabs}<h1>Understanding sources</h1><div class="formation-review"><p><strong>Text verification:</strong> ${esc(data.reviewStatus.textVerification)}</p><p><strong>Theological review:</strong> ${esc(data.reviewStatus.theologicalReview)}</p><p>Source-type labels and reading sequences are editorial navigation. They do not confer ecclesiastical approval.</p></div><div class="formation-guide">${data.sourceGuide.map(g=>`<article><h2>${esc(g.title)}</h2><p>${esc(g.description)}</p></article>`).join('')}</div><section><h2>Terminology and language forms</h2><p>Definitions link the original reading and its location. Pronunciation is included only when verified; this edition supplies no generated phonetics or synthetic pronunciation.</p><label>Search terminology<input type="search" data-filter="q" value="${esc(query.q)}"></label><p id="formation-count" role="status"></p><div id="formation-results"></div></section><p><a class="button secondary" href="#/sources">Complete source library</a></p>`;
      const render=()=>{const found=terms.filter(s=>norm([s.term.term,...s.languageForms].join(' ')).includes(norm(query.q)));root.querySelector('#formation-count').textContent=`${found.length} terminology records`;root.querySelector('#formation-results').innerHTML=found.map(s=>`<article class="formation-term"><h3><a href="#/term/${esc(s.termId)}">${esc(s.term.term)}</a></h3>${s.languageForms.length?`<p>${s.languageForms.map(esc).join(' · ')}</p>`:''}<p class="reading-locator">${esc(s.locator)}</p><p class="reading-attribution">${esc(s.pronunciationStatus)}</p>${sourceRecord(sources.get(s.sourceId))}</article>`).join('')||'<p>No terms found.</p>';replace(keys,query);};on('input',e=>{if(e.target.dataset.filter==='q'){query.q=e.target.value;render();}});render();return;
    }
    root.innerHTML=`${tabs}<h1>Study page not found</h1>`;
  }
  return {load,mount,unmount};
})();
